#!/usr/bin/env python3
"""从 MCP 返回的原始 JSON 提取并保存每个 listCode 为独立文件"""
import json, os, shutil

MCP_DIR = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), "data", "mcp")
os.makedirs(MCP_DIR, exist_ok=True)

def save_component(key, val):
    """保存单个 listCode 数据，包装在 ok/data 信封中"""
    list_code = val.get("listCode", key)
    wrapper = {"ok": True, "data": {key: val}}
    path = os.path.join(MCP_DIR, f"{list_code}.json")
    with open(path, "w", encoding="utf-8") as f:
        json.dump(wrapper, f, ensure_ascii=False, indent=2)
    print(f"  {list_code}.json ({val.get('totalItems','?')} items)")

# ======== Call 1: macro_calendar_future (已保存，复制一份 calendar_future.json) ========
c1_path = os.path.join(MCP_DIR, "macro_calendar_future.json")
if os.path.exists(c1_path):
    shutil.copy2(c1_path, os.path.join(MCP_DIR, "calendar_future.json"))
    print("Call 1: calendar_future.json copied")

# ======== Call 2: macro_us_inflation + macro_us_employment (从大文件读取) ========
big_file = r"C:\Users\chen8\.workbuddy\projects\d-WorkBuddy-2026-06-12-13-25-25-macro-timeline\153fb0cf-2128-41ac-961f-d55c745dc5c2\tool-results\mcp-connector-proxy-westock-mcp_data_macro-1785374481966-9158df.txt"
print(f"\nCall 2: Reading {big_file}...")
with open(big_file, "r", encoding="utf-8") as f:
    c2 = json.load(f)
for key, val in c2.get("data", {}).items():
    save_component(key, val)

